{
  "version": 1,
  "themeUuid": "294abe4b-1f38-4e37-a03e-6320408188fd",
  "themeConfig": {
    "sourceTable": "mamba_fact_transfer_in",
    "patientIdColumn": "client_id",
    "dateColumn": "encounter_date",
    "locationColumn": "",
    "fields": [],
    "conditions": [
      {
        "key": "tranfer_in_date",
        "label": "Transfer In Date",
        "handler": "DATE_RANGE",
        "column": "transfer_in_date",
        "operator": "BETWEEN",
        "valueType": "date"
      }
    ]
  },
  "conditions": [
    {
      "key": "tranfer_in_date",
      "operator": "BETWEEN",
      "valueType": "date",
      "value": {
        "start": ":stratDate",
        "end": ":endDate"
      }
    }
  ],
  "sqlPreview": "SELECT\n  COUNT(*) AS total\nFROM mamba_fact_transfer_in a\nJOIN mamba_fact_patients_latest_patient_demographics mdp\n  ON mdp.patient_id = a.client_id\nWHERE a.encounter_date &gt;= ':startDate'\n  AND a.encounter_date &lt;  ':endDate'\n  AND a.transfer_in_date BETWEEN ':stratDate' AND ':endDate'\n  AND mdp.birthdate IS NOT NULL\n  AND mdp.gender IS NOT NULL\n;"
}
